<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useStudyStore } from '../stores/useStudyStore'
import WeekUploadModal from '../components/cycle/WeekUploadModal.vue'
import WeekDetailDrawer from '../components/cycle/WeekDetailDrawer.vue'
import { useGoogleServices } from '../composables/useGoogleServices'
const store = useStudyStore(); const upload = ref<typeof store.weeks[0] | null>(null); const detail = ref<typeof store.weeks[0] | null>(null); onMounted(store.hydrate)
const google = useGoogleServices()
async function scheduleWeek() { if (detail.value) { try { await google.scheduleWeekSessions(detail.value) } catch { /* El composable ya muestra el toast adecuado. */ } } }
async function rescheduleWeek() { if (detail.value) { try { await google.reschedulePendingSessions(detail.value) } catch { /* El composable ya muestra el toast adecuado. */ } } }
const nextSession = () => { const week = store.weeks.find(item => item.subtemas.some(sub => !sub.completado)); const sub = week?.subtemas.find(item => !item.completado); return week && sub ? `/session/${week.modulo}/${week.semana}/${sub.id}` : '/' }
const status = (state: string) => state === 'completada' ? 'Completada' : state === 'procesada' ? 'En progreso' : 'Pendiente'
</script>
<template><div><main class="mx-auto max-w-7xl px-5 py-8"><div class="mb-6 max-w-2xl"><p class="font-bold uppercase tracking-widest text-indigo-400">Tu ciclo de aprendizaje</p><h1 class="mt-2 text-4xl font-black text-white">Matemática discreta, sin distracciones.</h1><p class="mt-3 text-lg text-slate-400">Organiza 4 módulos × 4 semanas y convierte cada concepto en práctica.</p></div><section class="mb-8 flex flex-wrap items-center justify-between gap-5 rounded-2xl border border-indigo-500/30 bg-indigo-950/30 p-6"><div><p class="text-sm font-bold uppercase tracking-widest text-indigo-300">Continuar donde lo dejaste</p><h2 class="mt-1 text-2xl font-bold text-white">{{ store.draft ? 'Retoma tu sesión guardada' : 'Tu siguiente concepto te espera' }}</h2><p class="mt-2 text-slate-400">{{ store.draft ? `Ejercicio ${store.draft.ejercicioActualIndex + 1} en curso` : 'Avanza con una sesión de enfoque.' }}</p></div><RouterLink :to="nextSession()" class="btn-primary">Iniciar Sesión de {{ store.settings.duracionSesionMinutos }} min</RouterLink></section><div class="grid gap-8 md:grid-cols-2"><section v-for="module in 4" :key="module"><h2 class="mb-3 text-xl font-bold text-white">Módulo {{ module }}</h2><div class="grid grid-cols-2 gap-3"><button v-for="week in store.weeks.filter(w => w.modulo === module)" :key="week.semana" class="card text-left hover:-translate-y-0.5 hover:border-indigo-500" @click="week.estado === 'pendiente' ? upload = week : detail = week"><span class="text-sm text-slate-400">Semana {{ week.semana }}</span><strong class="mt-2 block text-white">{{ status(week.estado) }}</strong><span class="mt-3 block h-1.5 rounded bg-slate-800"><span class="block h-full rounded bg-indigo-500" :style="{ width: week.estado === 'completada' ? '100%' : week.estado === 'procesada' ? '45%' : '0%' }" /></span></button></div></section></div></main><WeekUploadModal v-if="upload" :week="upload" @close="upload = null" @processed="store.updateWeek($event); upload = null; detail = $event" /><WeekDetailDrawer v-if="detail" :week="detail" @close="detail = null" @schedule="scheduleWeek" @reschedule="rescheduleWeek" @exam="$router.push(`/exam/${detail.modulo}/${detail.semana}`)" /></div></template>
